#!/usr/bin/env python3
"""SOC Reporting Capstone: evidence-backed incident report generator.

Standard-library only. Input: case.json
Output: incident-report.md
"""
from __future__ import annotations

import json
import sys
from datetime import datetime, timezone
from pathlib import Path

REQUIRED = ("case_id", "status", "severity", "summary", "timeline", "findings", "actions", "references")


def parse_utc(value: str) -> datetime:
    dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    if dt.tzinfo is None:
        raise ValueError(f"timestamp has no timezone: {value}")
    return dt.astimezone(timezone.utc)


def validate_case(case: dict) -> list[str]:
    errors: list[str] = []
    for field in REQUIRED:
        if field not in case:
            errors.append(f"missing required field: {field}")
    if errors:
        return errors

    for index, item in enumerate(case["timeline"], 1):
        try:
            parse_utc(item["time"])
        except (KeyError, ValueError) as exc:
            errors.append(f"timeline[{index}] invalid time: {exc}")
        if not item.get("source") or not item.get("event"):
            errors.append(f"timeline[{index}] requires source and event")

    for index, finding in enumerate(case["findings"], 1):
        if not finding.get("claim") or not finding.get("support"):
            errors.append(f"finding[{index}] requires claim and support")

    for index, action in enumerate(case["actions"], 1):
        for field in ("action", "owner", "status"):
            if not action.get(field):
                errors.append(f"action[{index}] missing {field}")

    return errors


def render_case(case: dict) -> str:
    timeline = sorted(case["timeline"], key=lambda x: parse_utc(x["time"]))
    lines = [
        f"# SOC Incident Report — {case['case_id']}",
        "",
        f"**Status:** {case['status']}",
        f"**Severity:** {case['severity']}",
        "",
        "## Summary",
        case["summary"],
        "",
        "## Timeline",
        "| Time (UTC) | Source | Event | Reference |",
        "|---|---|---|---|",
    ]
    for item in timeline:
        ref = item.get("reference", "")
        lines.append(f"| {parse_utc(item['time']).isoformat()} | {item['source']} | {item['event']} | {ref} |")

    lines += ["", "## Findings", "", "| Claim | Support | Limitation |", "|---|---|---|"]
    for finding in case["findings"]:
        lines.append(f"| {finding['claim']} | {finding['support']} | {finding.get('limitation', '')} |")

    lines += ["", "## Response Actions", ""]
    for action in case["actions"]:
        lines.append(f"- **{action['status']}** — {action['action']} — owner: {action['owner']}")

    lines += ["", "## Open Gaps", ""]
    gaps = case.get("gaps", [])
    if gaps:
        lines.extend(f"- {gap}" for gap in gaps)
    else:
        lines.append("- None documented.")

    lines += ["", "## References", ""]
    for ref in case["references"]:
        lines.append(f"- {ref}")

    lines += ["", "## Report QA Note", "", "This document was generated from structured case data. Human review is required before operational or external distribution.", ""]
    return "\n".join(lines)


def main() -> int:
    if len(sys.argv) != 2:
        print("Usage: python soc_report.py case.json", file=sys.stderr)
        return 2

    source = Path(sys.argv[1])
    case = json.loads(source.read_text(encoding="utf-8"))
    errors = validate_case(case)
    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1

    output = source.with_name("incident-report.md")
    output.write_text(render_case(case), encoding="utf-8")
    print(f"Wrote {output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

